lesson.code:
class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance
    def deposit(self, amount):
        self.balance += amount

acct = BankAccount("Alex", 100)
acct.deposit(50)
print(f"{acct.owner}'s balance: ${acct.balance}")

class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade
    def get_summary(self):
        return f"{self.name} is in grade {self.grade}"

s = Student("Maya", 10)
print(s.get_summary())

class Book:
    library_name = "City Central"  # Class attribute (shared)
    def __init__(self, title):
        self.title = title        # Instance attribute (unique)
    def __str__(self):
        return f"Book: '{self.title}'"

b = Book("Clean Code")
print(b)                       # Calls __str__
print("Library:", b.library_name)

# Showing proper self usage
class Cat:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return f"{self.name} says meow"

c = Cat("Luna")
print(c.speak())

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __str__(self):
        return f"Point({self.x}, {self.y})"

print(Point(3, 4))

