class BankAccount:
    def __init__(self, balance):
        self.balance = balance
    def withdraw(self, amount):
        if amount <= self.balance:
            self.balance -= amount
            return True
        return False

acct = BankAccount(100)
acct.withdraw(40)
print(acct.balance)

