class Student:
    def __init__(self, name):
        self.name = name
        self.scores = []
    def add_score(self, s):
        self.scores.append(s)
    def average(self):
        return sum(self.scores) / len(self.scores) if self.scores else 0
s = Student('Alex')
s.add_score(90)
s.add_score(80)
print(f"{s.name}: {s.average():.1f}")
